param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-byte-residue-core-20260915';$seed='D:\projects\AIMA-public-replay-weight-buckets-20260915';$sha='31f809d30017fc12dfabe7a1f0a573956ce00370';$bundle='D:\projects\byte-residue-core-31f809d.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '1633a208c23ae0c8d51b1bca8117ece503519699b7af179e3697d566a10f6056'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\byte-residue-core';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\byte_residue_core_selftest.cpp';$exe=Join-Path $build 'byte-residue-core.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceFiles=@($source,(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
$sourceInputs=@($sourceFiles|Sort-Object -Unique|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated BF16-derived integer cores with headroom5 and6, all original BF16 encodings and two-matrix recovery diagnostics';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Isolated two-matrix integer core: one FP16 estimate and one unsigned8 matrix product recover the low-byte congruence class under the explicit error128 condition. Both116-byte prepared row ranges retain original words, exception masks and trailing metadata. Compare2097152 dots per range against independent CPU integers and original four-IU8 hardware products, including all65536 original BF16 patterns. Report every recovery rejection and error-condition violation without declaring hardware proof. Only a numerically passing finite range enters16/64/256-group sequence comparison, with one warmup and three rotated attempts, all inputs and guards. Timings exclude preparation and canonical carry/exception costs. No model or product dispatcher changes.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=150
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@();$timeout=240
}
$out=Join-Path $repo ('build\byte-residue-core-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $cases=@($reports|Where-Object {$_.kind -eq 'byte_residue_core_native'});$sequences=@($reports|Where-Object {$_.kind -eq 'byte_residue_core_sequence'})
 if($cases.Count -ne 2 -or @($cases|Where-Object {$_.headroom -eq 5}).Count -ne 1 -or @($cases|Where-Object {$_.headroom -eq 6}).Count -ne 1){throw 'Incomplete byte residue diagnostics'}
 foreach($r in $cases){
  if($r.dot_positions -ne 2097152 -or $r.integer_control_mismatches -ne 0 -or $r.residue_mismatches -ne 0 -or -not $r.redzones_pass -or -not $r.immutable_inputs){throw 'Integer control or storage failed'}
  $matching=@($sequences|Where-Object {$_.headroom -eq $r.headroom})
  $eligible=($r.accepted_recovery_mismatches -eq 0 -and $r.recovery_rejections -eq 0 -and $r.conditional_bound_violations -eq 0)
  if(($eligible -and $matching.Count -ne 6) -or (-not $eligible -and $matching.Count -ne 0)){throw 'Sequence diagnostic gating differs'}
 }
 foreach($r in $sequences){if($r.mismatches -ne 0 -or -not $r.all_attempts_verified -or -not $r.redzones_pass -or -not $r.immutable_inputs -or $r.samples_ms.Count -ne 3){throw 'Byte residue sequence mismatch'}}

}
